solution.javascript:
function swimInWater(grid) {
  const n = grid.length;
  const dirs = [[0,1],[1,0],[0,-1],[-1,0]];
  const pq = [[grid[0][0], 0, 0]];
  const vis = Array(n).fill(null).map(() => Array(n).fill(false));
  vis[0][0] = true;
  while (pq.length) {
    pq.sort((a,b) => b[0] - a[0]);
    const [t, r, c] = pq.pop();
    if (r === n-1 && c === n-1) return t;
    for (const [dr, dc] of dirs) {
      const nr = r+dr, nc = c+dc;
      if (nr>=0&&nr<n&&nc>=0&&nc<n&&!vis[nr][nc]) { vis[nr][nc]=true; pq.push([Math.max(t, grid[nr][nc]), nr, nc]); }
    }
  }
  return -1;
}

solution.cpp:
int swimInWater(vector<vector<int>>& grid) {
    int n = grid.size();
    int dirs[4][2] = {{0,1},{1,0},{0,-1},{-1,0}};
    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;
    pq.push({grid[0][0], 0, 0});
    vector<vector<bool>> vis(n, vector<bool>(n)); vis[0][0] = true;
    while (!pq.empty()) {
        auto [t, r, c] = pq.top(); pq.pop();
        if (r==n-1 && c==n-1) return t;
        for (int d=0; d<4; d++) {
            int nr = r+dirs[d][0], nc = c+dirs[d][1];
            if (nr>=0&&nr<n&&nc>=0&&nc<n&&!vis[nr][nc]) { vis[nr][nc]=true; pq.push({max(t, grid[nr][nc]), nr, nc}); }
        }
    }
    return -1;
}
